-- Guest Hub H11 (24 Nov 2026, Ahmed — DECISIONS.md 2026-11-24 «Guest Hub H11»): the fixes from the weekly review of
-- 19–24 Nov. Generated by scripts/hub-h11-migration.mjs from scripts/hub-h11-migration.src.sql and the latest definitions
-- of the functions it edits — never edited once applied (CLAUDE.md §12: a fix is a new migration).
--   The turns of one conversation run one at a time: the claim locks the conversation before it looks for a running turn
--   (two claims at once both saw none). The history hands each message's kind and time (the 2-minute dedupe).
--   A guest asking about a booking request still waiting re-alerts the staff on shift; a chat request still a request
--   after its 15-minute escalation is re-alerted every 60 minutes, at most 3 more; the daily report's faults count the
--   requests left more than 15 minutes.
--   «أرغب في التمديد» asks the date first: an open «extend» draft holds the conversation for the guest's date.
--   Three knowledge cards, the landline card in Ahmed's wording, the reception extension Airport Road's only; the H11 bank
--   as lab items; h10-01 / h10-02 «في أقرب وقت».
-- No unit mode, licence or switch changes. No phone number in this file. Every UPDATE / DELETE carries a WHERE.

-- ───────────────────────────────────────────── 1. the schema ─────────────────────────────────────────────

-- the extension's date waits on an open draft of its own (the guest's next message is its date)
alter table public.hub_drafts drop constraint hub_drafts_kind_check;
alter table public.hub_drafts add constraint hub_drafts_kind_check check (kind in ('stay', 'table', 'hall', 'group', 'package', 'extend'));

-- the hourly re-alerts of a chat booking request still unconfirmed after its 15-minute escalation (at most 3)
alter table public.hub_handoffs add column realerts integer not null default 0;
alter table public.hub_handoffs add column realert_at timestamptz;
alter table public.hub_handoffs add constraint hub_handoffs_realerts_check check (realerts between 0 and 3);
comment on column public.hub_handoffs.realerts is 'H11 (24 Nov 2026): the re-alerts of a booking_request row sent every 60 minutes after its 15-minute escalation while the reservation is still a request — at most 3.';

