-- ───────────────────────────────────────────── 3. the functions it edits (the latest definitions) ─────────────────────────────────────────────

create or replace function public.hub_turn_claim(p_turn uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  t public.hub_turns;
  c public.hub_conversations;
  u public.hub_units;
  ch public.hub_channels;
  g public.guest_profiles;
  st jsonb;
  v_mode text;
  v_state text;
  v_draft jsonb;
  v_first boolean;
  v_rate jsonb;
  v_text text;
  v_phase text;
begin
  select * into t from public.hub_turns where id = p_turn for update skip locked;
  if t.id is null then return jsonb_build_object('claimed', false, 'reason', 'taken'); end if;
  if t.status <> 'pending' then return jsonb_build_object('claimed', false, 'reason', t.status); end if;
  if t.due_at > now() then return jsonb_build_object('claimed', false, 'reason', 'not_due', 'due_at', t.due_at); end if;
  -- H11 (Ahmed, 24 Nov 2026 — «تم، أضفنا ذلك إلى طلبك.» twice in 5 seconds): the turns of one conversation one at a time —
  -- the conversation is locked BEFORE looking for a running turn, so a second claim waits for the first to commit and sees it
  perform 1 from public.hub_conversations where id = t.conversation_id for update;
  if exists (select 1 from public.hub_turns x where x.conversation_id = t.conversation_id and x.status = 'running') then
    return jsonb_build_object('claimed', false, 'reason', 'busy');
  end if;
  select * into c from public.hub_conversations where id = t.conversation_id for update;
  select * into u from public.hub_units where id = c.unit_id;
  select * into ch from public.hub_channels where id = c.channel_id;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  st := internal.hub_assistant_state(u);
  if c.state = 'closed' or not (st ->> 'active')::boolean or g.hub_blocked_at is not null then
    update public.hub_turns set status = 'skipped', finished_at = now(), error = coalesce(case when c.state = 'closed' then 'closed' when g.hub_blocked_at is not null then 'blocked' end, st ->> 'reason') where id = t.id;
    perform internal.hub_to_team(c, coalesce(st ->> 'reason', 'assistant_off'));
    return jsonb_build_object('claimed', false, 'reason', coalesce(st ->> 'reason', 'closed'));
  end if;
  v_mode := case st ->> 'mode' when 'test' then 'test' when 'shadow' then 'shadow' else 'live' end;
  v_state := case when v_mode = 'test' then coalesce(c.test_state, 'new') else c.state end;
  -- H6c: waiting (handed, no staff reply) / resume (staff silent for the branch's minutes) / null (silent)
  v_phase := case when v_mode = 'test' then case when v_state = 'human' then 'waiting' end when c.state = 'human' then internal.hub_human_phase(c, u) end;
  update public.hub_turns set status = 'running', claimed_at = now(), started_at = coalesce(started_at, now()), attempts = attempts + 1, mode = v_mode,
                              kind = case when v_state = 'closed' or (v_state = 'human' and v_phase is null) then 'tag' else kind end,
                              -- «وضع الاستعداد»: no staff reply in the wait — the assistant answers after it
                              standby_outcome = case when standby_until is not null and standby_outcome is null and kind = 'reply'
                                                       and not (v_state = 'closed' or (v_state = 'human' and v_phase is null)) then 'assistant' else standby_outcome end
   where id = t.id returning * into t;
  select to_jsonb(d) - 'is_test' into v_draft from public.hub_drafts d where d.conversation_id = c.id and d.status = 'open' and d.sim = (v_mode = 'test');
  v_first := not exists (select 1 from public.hub_messages m where m.conversation_id = c.id and m.direction = 'out' and m.kind <> 'note'
                          and m.status not in ('rejected', 'superseded', 'failed') and (v_mode = 'test' or m.status <> 'test'));
  select string_agg(m.body, ' ' order by m.sent_at) into v_text from public.hub_messages m where m.id = any (t.inbound_message_ids);
  -- the rate limits of spec §7.4: guest messages processed per phone per hour, assistant replies per conversation per
  -- hour, the same text three times in ten minutes
  v_rate := jsonb_build_object(
    'phone_hour', (select coalesce(sum(cardinality(x.inbound_message_ids)), 0) from public.hub_turns x join public.hub_conversations y on y.id = x.conversation_id
                    where y.guest_profile_id = g.id and x.id <> t.id and x.status in ('done', 'running') and x.kind = 'reply' and x.created_at > now() - interval '1 hour'),
    -- H10 (bd27baf4 — three cards counted as three replies): the assistant's replies by TURN
    'replies_hour', (select count(distinct m.turn_id) from public.hub_messages m where m.conversation_id = c.id and m.author = 'assistant' and m.direction = 'out'
                      and m.created_at > now() - interval '1 hour' and not coalesce((m.payload ->> 'notice')::boolean, false)),
    'repeated', (select count(*) >= 2 from public.hub_messages m where m.conversation_id = c.id and m.direction = 'in' and m.author = 'guest'
                  and not (m.id = any (t.inbound_message_ids)) and m.created_at > now() - interval '10 minutes'
                  and btrim(lower(coalesce(m.body, ''))) = btrim(lower(coalesce(v_text, ''))) and coalesce(v_text, '') <> '')
                  -- Ahmed, 14 Nov 2026 (H6 pass 4): a repeat is suppressed ONLY when the assistant already answered that same text in
                  -- this episode, and answered its LATEST earlier copy (that copy's reply turn sent the guest a message) — so a copy
                  -- whose earlier copies got no reply from the assistant (the team owned the conversation, the model failed …) is
                  -- answered; 21:51 of 14 Nov: the 21:48 copies came while the phone owned it, so the third is answered
                  and coalesce((select exists (select 1 from public.hub_turns z join public.hub_messages o on o.turn_id = z.id
                                                where z.conversation_id = c.id and m2.id = any (z.inbound_message_ids) and z.kind = 'reply' and z.status = 'done'
                                                  and o.direction = 'out' and o.author = 'assistant' and o.status not in ('test', 'rejected', 'superseded', 'failed'))
                                  from public.hub_messages m2
                                 where m2.conversation_id = c.id and m2.direction = 'in' and m2.author = 'guest' and not (m2.id = any (t.inbound_message_ids))
                                   and btrim(lower(coalesce(m2.body, ''))) = btrim(lower(coalesce(v_text, '')))
                                 order by m2.created_at desc, m2.sent_at desc, m2.id desc limit 1), false),
    'phone_max', internal.hub_setting_int('hub_rate_phone_hour', 30), 'replies_max', internal.hub_setting_int('hub_rate_replies_hour', 20));
  return jsonb_build_object(
    'claimed', true,
    'turn', jsonb_build_object('id', t.id, 'kind', t.kind, 'mode', v_mode, 'attempts', t.attempts, 'is_test', t.is_test),
    'conversation', jsonb_build_object('id', c.id, 'state', v_state, 'real_state', c.state, 'state_before_human', c.state_before_human, 'human_phase', v_phase, 'human_reason', c.human_reason,
      'language', coalesce(c.language, g.language), 'window_expires_at', c.window_expires_at, 'failed_understandings', c.failed_understandings,
      'priority', c.priority, 'topics', to_jsonb(c.topics), 'tags', to_jsonb(c.tags), 'out_of_scope', c.out_of_scope, 'first_reply', v_first,
      'created_at', c.created_at, 'is_test', c.is_test),
    'unit', jsonb_build_object('id', u.id, 'key', u.key, 'kind', u.kind, 'branch', u.branch_slug, 'name_ar', u.name_ar, 'name_en', u.name_en,
      'mode', u.assistant_mode, 'skills', to_jsonb(u.skills), 'persona', u.persona_live,
      -- H7: «الفويس» and «الصور»
      'media', jsonb_build_object('voice', u.voice_on, 'images', u.images_on),
      'venue', (select jsonb_build_object('name_ar', v.name_ar, 'name_en', v.name_en, 'menu', v.menu) from public.dining_venues v where v.id = u.dining_venue_id)),
    'channel', jsonb_build_object('address', ch.address, 'sending_enabled', ch.sending_enabled),
    'guest', jsonb_build_object(
      -- a name from a past booking only (spec §2.9) — never the WhatsApp profile name
      'first_name', case when exists (select 1 from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and not r.is_test)
                         then nullif(split_part(btrim(coalesce(g.name, '')), ' ', 1), '') end,
      'returning', exists (select 1 from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and r.check_out <= internal.riyadh_today() and not r.is_test),
      'language', g.language,
      -- H8: a returning guest's previous room (a confirmed past stay on the same phone) — its card comes first
      'last_room', (select jsonb_build_object('branch', r.branch, 'room', rt.slug) from public.reservations r join public.room_types rt on rt.id = r.room_type_id
                     where r.phone = g.phone and r.status = 'confirmed' and not r.is_test and r.check_out <= internal.riyadh_today() order by r.check_out desc limit 1),
      -- H8: the «إياب» members' prices only for a member with recorded consent (applied by code, never inferred)
      'member', g.club_joined_at is not null and g.consent = 'granted',
      -- H8: «يُعامَل كضيف للتجربة» — a test reservation that never takes a room
      'test_guest', internal.hub_test_guest(g.phone)),
    -- H8: the live «إياب» members' codes of this branch, for a member only
    'member_codes', case when g.club_joined_at is not null and g.consent = 'granted' then
      (select coalesce(jsonb_agg(distinct o.promo_code), '[]'::jsonb) from public.offers o
        where o.audience = 'members' and o.category = 'individuals' and o.live is not null and o.archived_at is null and not o.is_test and o.promo_code is not null
          and (o.valid_to is null or o.valid_to >= internal.riyadh_today()) and (o.branches is null or cardinality(o.branches) = 0 or u.branch_slug = any (o.branches)))
      else '[]'::jsonb end,
    'messages', (select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'kind', m.kind, 'body', m.body, 'payload', m.payload, 'sent_at', m.sent_at,
                                                              'provider_message_id', m.provider_message_id,
                                                              -- H7: the stored file and a transcript already made (a retried turn)
                                                              'media_path', m.media_path, 'media_mime', m.media_mime, 'transcript', m.transcript) order by m.sent_at, m.created_at), '[]')
                   from public.hub_messages m where m.id = any (t.inbound_message_ids)),
    'history', (select coalesce(jsonb_agg(jsonb_build_object('author', case when h.direction = 'in' then 'guest' when h.author in ('staff', 'phone') then 'staff' else 'us' end, 'body', coalesce(h.body, h.transcript), 'kind', h.kind, 'at', h.sent_at) order by h.sent_at), '[]')
                  from (select m.* from public.hub_messages m
                         where m.conversation_id = c.id and not (m.id = any (t.inbound_message_ids)) and m.kind <> 'note' and coalesce(m.body, m.transcript) is not null
                           and m.status not in ('rejected', 'superseded', 'failed', 'pending_approval') and (v_mode = 'test' or m.status <> 'test')
                         order by m.sent_at desc limit 12) h),
    'draft', v_draft,
    -- H9: a departure check sent today and not answered yet — a typed answer («بمدد يومين», «طالع الساعة 11») is understood
    -- as «سأغادر في موعدي» / «أرغب في التمديد»; a late check-out question stays an ordinary question
    'departure', (select jsonb_build_object('id', d.id, 'ref', d.nazeel_ref) from public.hub_departures d
                   where d.phone = g.phone and d.branch_slug = u.branch_slug and d.answer is null and d.is_test = c.is_test
                     and d.check_state in ('accepted', 'sent', 'delivered', 'read', 'test') and d.departure_date = internal.riyadh_today()
                   order by d.check_at desc limit 1),
    -- H7: the unit's transcribed seconds today and the cap
    'voice', internal.hub_voice_state(u.id),
    -- the guest's own bookings (same phone) for a booking-status answer: ref, status, branch, dates only
    -- H10: with the room, the party, breakfast and the recorded cancellation (a reply never contradicts it; the alternatives
    -- of a cancelled stay)
    'bookings', (select coalesce(jsonb_agg(jsonb_build_object('ref', r.ref, 'status', r.status, 'branch', r.branch, 'check_in', r.check_in, 'check_out', r.check_out,
                                           'room', (select rt.slug from public.room_types rt where rt.id = r.room_type_id), 'adults', r.adults, 'children', r.children,
                                           'breakfast', r.breakfast, 'cancel_reason_code', r.cancel_reason_code, 'cancelled_at', r.cancelled_at, 'source', r.booking_source)
                                           order by r.check_in desc), '[]')
                   from (select * from public.reservations r where r.phone = g.phone and (r.is_test = c.is_test or (r.is_test and internal.hub_test_guest(g.phone)))
                          order by r.created_at desc limit 5) r),
    -- H10: every message we sent this guest outside the chat's text in the last 7 days — the booking templates (rendered by
    -- the engine with the variables they carried), the departure check, the review request, the arrival reminder; no phone
    'sent', (select coalesce(jsonb_agg(s.j order by s.at), '[]') from (
               select w.created_at as at, jsonb_build_object('at', w.created_at, 'template', w.template, 'meta_template', w.meta_template, 'language', w.language,
                        'status', w.status, 'ref', r.ref, 'branch', r.branch, 'check_in', r.check_in, 'check_out', r.check_out, 'total', r.total,
                        'room', (select rt.slug from public.room_types rt where rt.id = r.room_type_id), 'room_name_ar', r.room_name_ar, 'room_name_en', r.room_name_en,
                        'first_name', split_part(btrim(coalesce(r.guest_name, '')), ' ', 1), 'reason_code', coalesce(w.reason_code, r.cancel_reason_code)) as j
                 from public.whatsapp_messages w join public.reservations r on r.id = w.reservation_id
                where r.phone = g.phone and w.is_test = c.is_test and w.status not in ('failed', 'queued') and w.created_at > now() - interval '7 days'
               union all
               select e.created_at, jsonb_build_object('at', e.created_at, 'template', e.template, 'language', e.language, 'status', e.status)
                 from public.eyab_messages e
                where e.profile_id = g.id and e.is_test = c.is_test and e.status not in ('failed', 'queued') and e.created_at > now() - interval '3 days'
                  and e.template in ('stay_review', 'arrival_reminder', 'eyab_welcome', 'eyab_offer')
               union all
               select d.check_at, jsonb_build_object('at', d.check_at, 'template', 'stay_checkout_check', 'status', d.check_state)
                 from public.hub_departures d
                where d.phone = g.phone and d.is_test = c.is_test and d.check_at is not null and d.check_at > now() - interval '3 days'
                  and d.check_state in ('accepted', 'sent', 'delivered', 'read', 'test')
               order by 1 desc limit 8) s),
    -- H10: the hand-off notice ONCE per hand-off episode — whether it already went since the hand-off (no staff reply since),
    -- and whether «ما زال طلبك…» is due (30 minutes since our last message)
    'handoff', case when c.state = 'human' and c.owner_kind is null then jsonb_build_object(
                 'notice_open', exists (select 1 from public.hub_messages m where m.conversation_id = c.id and m.author = 'assistant' and m.direction = 'out'
                                          and m.created_at >= c.state_changed_at and m.status not in ('failed', 'rejected', 'superseded')
                                          and (coalesce((m.payload ->> 'notice')::boolean, false) or coalesce((m.payload ->> 'handoff')::boolean, false))),
                 'waiting_line_due', coalesce((select max(m.created_at) from public.hub_messages m where m.conversation_id = c.id and m.author = 'assistant' and m.direction = 'out'
                                                and m.status not in ('failed', 'rejected', 'superseded')), c.state_changed_at) <= now() - interval '30 minutes')
               end,
    -- H10 (5fb7aac4): a staff or phone message of the last 3 hours asked about leaving or extending («خروج ولا تمديد؟»)
    'staff_departure_q', exists (select 1 from public.hub_messages m where m.conversation_id = c.id and m.direction = 'out' and m.author in ('staff', 'phone')
                                   and m.created_at > now() - interval '3 hours' and coalesce(m.body, '') ~* '(خروج|تمديد|مغادر|تطلع|تغادر|تمدد|check ?out|extend|leaving)'),
    'licences', (select coalesce(jsonb_object_agg(l.topic_key, l.mode), '{}') from public.hub_licences l where l.unit_id = u.id),
    'topics', (select coalesce(jsonb_agg(jsonb_build_object('key', x.key, 'label_en', x.label_en, 'label_ar', x.label_ar, 'parent_key', x.parent_key, 'always_handoff', x.always_handoff) order by x.sort, x.key), '[]')
                 from public.hub_topics x where x.status = 'active' and not x.is_test),
    'settings', jsonb_build_object(
      'confidence_floor', coalesce((select (s.value #>> '{}')::numeric from public.settings s where s.key = 'hub_confidence_floor'), 0.7),
      'cards_per_turn', internal.hub_setting_int('hub_cards_per_turn', 5), 'reply_max_chars', internal.hub_setting_int('hub_reply_max_chars', 600),
      'failed_max', internal.hub_setting_int('hub_failed_understanding_max', 2), 'resume_minutes', internal.hub_resume_minutes(u.branch_slug), 'group_min_rooms', internal.hub_setting_int('hub_group_min_rooms', 5),
      'models', (select s.value from public.settings s where s.key = 'hub_models'), 'prices', (select s.value from public.settings s where s.key = 'hub_model_prices'),
      -- the site's own switch: prices only while the branch shows them (spec §2.5 rule 11)
      'show_prices', coalesce((select (s.value ->> u.branch_slug)::boolean from public.settings s where s.key = 'show_prices'), false),
      -- H8: the branch's «الحجز الفوري» (off keeps the booking link as the fallback) and the instant limits (the reason texts)
      'instant_booking', coalesce((select (s.value ->> u.branch_slug)::boolean from public.settings s where s.key = 'instant_booking'), false),
      'limits', coalesce(internal.setting('instant_limits'), '{"same_day_cutoff": "20:00", "max_nights": 30}'::jsonb)),
    -- the shared forbidden list the guard reads (internal.hub_forbidden_terms — never copied)
    'forbidden', to_jsonb(internal.hub_forbidden_terms()),
    'rate', v_rate,
    'budget', internal.hub_budget_state(),
    'today', internal.riyadh_today());
end;
$$;

create or replace function public.hub_turn_finish(p_turn uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  t public.hub_turns;
  c public.hub_conversations;
  m jsonb;
  v_cost numeric := 0;
  v_one numeric;
  v_to text := nullif(p ->> 'state', '');
  v_from text;
  v_test boolean;
  v_status text;
  v_out jsonb := '[]'::jsonb;
  v_id uuid;
  v_topics text[] := array(select jsonb_array_elements_text(coalesce(p -> 'topics', '[]'::jsonb)));
  v_draft jsonb := p -> 'draft';
  v_send boolean := false;
  v_seq integer := 0;
  v_unit uuid;
  v_ready boolean;
  v_mx jsonb;
  v_capped boolean := false;
  v_move public.hub_units;
  v_here public.hub_units;
begin
  select * into t from public.hub_turns where id = p_turn for update;
  if t.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  if t.status <> 'running' then return jsonb_build_object('ok', false, 'reason', 'not_running', 'status', t.status); end if;
  select * into c from public.hub_conversations where id = t.conversation_id for update;
  v_test := t.mode = 'test';
  -- the models: every call counts in the budget (test runs included)
  for m in select * from jsonb_array_elements(coalesce(p -> 'models', '[]'::jsonb)) loop
    if m ->> 'layer' in ('understand', 'tag', 'compose', 'summary', 'vision') and coalesce((m ->> 'input_tokens')::bigint, 0) + coalesce((m ->> 'output_tokens')::bigint, 0) > 0 then
      v_one := internal.hub_usage_add(t.unit_id, m ->> 'layer', 'turn', m ->> 'model', (m ->> 'input_tokens')::bigint, (m ->> 'output_tokens')::bigint, t.is_test);
      v_cost := v_cost + v_one;
    end if;
  end loop;
  -- H7: the transcriptions (OpenAI, per minute — never in the Claude budget) and what each voice note / image became: the
  -- transcript, its length and language, the image's category, the outcome — never anything read from an image
  for v_mx in select * from jsonb_array_elements(coalesce(p -> 'audio', '[]'::jsonb)) loop
    if coalesce((v_mx ->> 'seconds')::numeric, 0) > 0 and coalesce(v_mx ->> 'model', '') ~ '^gpt-[a-z0-9.-]{3,60}$' then
      perform internal.hub_audio_add(t.unit_id, 'turn', v_mx ->> 'model', (v_mx ->> 'seconds')::numeric, t.is_test);
    end if;
  end loop;
  for v_mx in select * from jsonb_array_elements(coalesce(p -> 'media', '[]'::jsonb)) loop
    if coalesce(v_mx ->> 'id', '') ~ '^[0-9a-f-]{36}$' then
      update public.hub_messages
         set transcript = case when v_mx ->> 'status' = 'transcribed' then left(nullif(btrim(v_mx ->> 'transcript'), ''), 8000) else transcript end,
             transcript_seconds = coalesce(case when jsonb_typeof(v_mx -> 'seconds') = 'number' then round((v_mx ->> 'seconds')::numeric, 2) end, transcript_seconds),
             transcript_language = coalesce(case when coalesce(v_mx ->> 'language', '') ~ '^[a-z]{2,8}$' then v_mx ->> 'language' end, transcript_language),
             media_category = coalesce(case when v_mx ->> 'category' in ('id_document', 'payment', 'screenshot', 'problem', 'place', 'other') then v_mx ->> 'category' end, media_category),
             media_status = case when v_mx ->> 'status' in ('transcribed', 'classified', 'too_long', 'voice_capped', 'failed_download', 'failed_transcribe', 'empty', 'unknown_language', 'failed_vision')
                                 then v_mx ->> 'status' else media_status end
       where id = (v_mx ->> 'id')::uuid and conversation_id = t.conversation_id and direction = 'in';
      if v_mx ->> 'status' = 'voice_capped' then v_capped := true; end if;
    end if;
  end loop;
  -- the unit's daily minutes used up: ONE alert email to the active admins per unit and Riyadh day (hub-agent); an alert
  -- of an earlier day is closed first
  if v_capped and not t.is_test then
    update public.hub_alerts set acknowledged_at = now()
     where kind = 'voice_cap' and unit_id = t.unit_id and acknowledged_at is null and not is_test
       and coalesce(payload ->> 'day', '') <> ((now() at time zone 'Asia/Riyadh')::date)::text;
    insert into public.hub_alerts (kind, unit_id, payload)
    values ('voice_cap', t.unit_id, jsonb_build_object('day', ((now() at time zone 'Asia/Riyadh')::date)::text, 'minutes', internal.hub_setting_int('hub_voice_daily_minutes', 60)))
    on conflict do nothing;
  end if;
  update public.hub_turns
     set status = case when p ->> 'status' in ('done', 'failed', 'skipped') then p ->> 'status' else 'done' end,
         error = nullif(left(p ->> 'error', 40), ''), understanding = p -> 'understanding', decision = p -> 'decision',
         models = coalesce(p -> 'models', '[]'::jsonb), cost_usd = v_cost, guard_refusals = coalesce(p -> 'guard_refusals', '[]'::jsonb), finished_at = now()
   where id = t.id;
  -- topics and language: real data, whatever the mode
  update public.hub_conversations
     set topics = (select coalesce(array_agg(distinct x), '{}') from (select unnest(topics) x union select unnest(v_topics)) q where x ~ '^[a-z0-9_]{2,60}$'),
         language = coalesce(case when p ->> 'language' in ('ar', 'en') then p ->> 'language' end, language),
         failed_understandings = case p ->> 'failed' when 'reset' then 0 when 'inc' then failed_understandings + 1 else failed_understandings end,
         out_of_scope = out_of_scope + case when coalesce((p ->> 'out_of_scope_inc')::boolean, false) then 1 else 0 end,
         tags = case when jsonb_typeof(p -> 'tags_add') = 'array'
                     then (select coalesce(array_agg(distinct x), '{}') from (select unnest(tags) x union select jsonb_array_elements_text(p -> 'tags_add')) q)
                     else tags end
   where id = c.id;
  if t.kind = 'tag' or p ->> 'status' in ('failed', 'skipped') and v_to is null then
    return jsonb_build_object('ok', true, 'messages', '[]'::jsonb, 'cost_usd', v_cost);
  end if;
  -- the draft (one open per conversation and run): a draft of another kind is superseded first
  if coalesce((p ->> 'draft_replace')::boolean, false) then
    update public.hub_drafts set status = 'superseded' where conversation_id = c.id and status = 'open' and sim = v_test;
  end if;
  if jsonb_typeof(v_draft) = 'object' then
    update public.hub_drafts set fields = coalesce(v_draft -> 'fields', fields), quote = coalesce(v_draft -> 'quote', quote), version = version + 1
     where conversation_id = c.id and status = 'open' and sim = v_test;
    if not found then
      -- H8: a new draft takes the id its buttons already carry (room cards, the summary)
      insert into public.hub_drafts (id, conversation_id, kind, sim, fields, quote, is_test)
      values (coalesce(case when v_draft ->> 'id' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then (v_draft ->> 'id')::uuid end, gen_random_uuid()),
              c.id, coalesce(v_draft ->> 'kind', 'stay'), v_test, coalesce(v_draft -> 'fields', '{}'::jsonb), v_draft -> 'quote', c.is_test);
    end if;
  end if;
  if nullif(p ->> 'draft_close', '') is not null then
    update public.hub_drafts set status = p ->> 'draft_close' where conversation_id = c.id and status = 'open' and sim = v_test and p ->> 'draft_close' in ('abandoned', 'failed', 'superseded');
  end if;
  -- the next state: in «تجربة» the run's own state (test_state); otherwise the conversation's
  if v_test then
    v_from := coalesce(c.test_state, 'new');
    if v_to is not null and v_to <> v_from then
      update public.hub_conversations set test_state = v_to where id = c.id;
      insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
      values (c.id, 'test', v_from, v_to, nullif(p ->> 'reason', ''), c.is_test);
    end if;
  else
    v_from := c.state;
    -- 19 Nov 2026 (Ahmed): a package order for the other branch — the conversation moves to that branch's unit right
    -- before the NEW hand-off (its row, staff alert and inbox follow the unit); the channel stays the guest's number
    if v_to = 'human' and (v_from <> 'human' or coalesce((p ->> 'resumed')::boolean, false)) and p ->> 'handoff_branch' in ('airport-road', 'shafa-road') then
      select * into v_move from public.hub_units where kind = 'branch' and branch_slug = p ->> 'handoff_branch' and status = 'active' limit 1;
      select * into v_here from public.hub_units where id = c.unit_id;
      if v_move.id is not null and v_move.id <> c.unit_id then
        insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
        values (c.id, 'transfer', v_here.key, v_move.key, 'package_branch', c.is_test);
        update public.hub_conversations set unit_id = v_move.id where id = c.id;
      end if;
    end if;
    if v_to = 'human' and v_from = 'human' then
      if coalesce((p ->> 'resumed')::boolean, false) then
        -- resumed after a staff reply and handed again (H6c): a new hand-off, with its own staff alert
        insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
        values (c.id, 'handoff', 'human', 'human', coalesce(nullif(p ->> 'reason', ''), 'handoff'), c.is_test);
        update public.hub_conversations
           set state_changed_at = now(), human_reason = coalesce(nullif(p ->> 'reason', ''), 'handoff'), owner_kind = null, owner_staff_id = null,
               priority = case when p ->> 'priority' = 'high' then 'high' else priority end, waiting_since = coalesce(waiting_since, now())
         where id = c.id;
      elsif p ->> 'resume_state' in ('inquiry', 'collecting', 'quoted', 'awaiting_confirmation', 'booked') then
        -- «بانتظار موظف»: where the assistant's flow stands while it waits (for the resume and «إعادة للمساعد»)
        update public.hub_conversations set state_before_human = p ->> 'resume_state' where id = c.id and state_before_human is distinct from p ->> 'resume_state';
      end if;
      if p ->> 'priority' = 'high' then
        update public.hub_conversations set priority = 'high' where id = c.id and priority <> 'high';
      end if;
    elsif v_to is not null and v_to <> v_from then
      if v_to = 'human' then
        insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
        values (c.id, 'handoff', v_from, 'human', coalesce(nullif(p ->> 'reason', ''), 'handoff'), c.is_test);
        update public.hub_conversations
           set state_before_human = case when v_from in ('new', 'inquiry', 'collecting', 'quoted', 'awaiting_confirmation', 'booked') then v_from else state_before_human end,
               state = 'human', state_changed_at = now(), human_reason = coalesce(nullif(p ->> 'reason', ''), 'handoff'), owner_kind = null, owner_staff_id = null,
               priority = case when p ->> 'priority' = 'high' then 'high' else priority end,
               waiting_since = coalesce(waiting_since, now())
         where id = c.id;
      elsif v_to = 'closed' then
        insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
        values (c.id, 'close', v_from, 'closed', coalesce(nullif(p ->> 'reason', ''), 'assistant'), c.is_test);
        update public.hub_conversations set state = 'closed', state_changed_at = now(), closed_at = now(), waiting_since = null where id = c.id;
      else
        insert into public.hub_conversation_events (conversation_id, kind, from_value, to_value, reason, is_test)
        values (c.id, 'state', v_from, v_to, nullif(p ->> 'reason', ''), c.is_test);
        update public.hub_conversations set state = v_to, state_changed_at = now(), owner_kind = 'assistant', owner_staff_id = null where id = c.id;
      end if;
    elsif p ->> 'priority' = 'high' then
      update public.hub_conversations set priority = 'high' where id = c.id;
    end if;
  end if;
  -- the staff alert's line and the booking ref or room (H6c), on the conversation's waiting hand-off
  if not v_test and (nullif(p ->> 'handoff_summary', '') is not null or nullif(p ->> 'handoff_ref', '') is not null or coalesce((p ->> 'handoff_add')::boolean, false)) then
    update public.hub_handoffs h
       set summary = coalesce(h.summary, nullif(left(btrim(p ->> 'handoff_summary'), 120), '')),
           ref_text = coalesce(h.ref_text, nullif(left(btrim(p ->> 'handoff_ref'), 40), '')),
           additions = h.additions + case when coalesce((p ->> 'handoff_add')::boolean, false) then 1 else 0 end
      from public.hub_conversations x
     where x.id = c.id and h.id = x.handoff_id;
  end if;
  -- the hand-off note (code-composed, spec §2.6): an internal note at the top of the thread, never sent
  if nullif(btrim(coalesce(p ->> 'note', '')), '') is not null then
    insert into public.hub_messages (conversation_id, channel_id, direction, author, kind, body, payload, idempotency_key, status, sent_at, turn_id, is_test)
    values (c.id, c.channel_id, 'out', 'system', 'note', left(btrim(p ->> 'note'), 2000), jsonb_build_object('handoff_note', true, 'test', v_test),
            'turn:' || t.id || ':note', case when v_test then 'test' else 'internal' end, now(), t.id, c.is_test)
    on conflict (idempotency_key) do nothing;
  end if;
  -- the messages: «تجربة» stored as test; «بموافقة الفريق» drafts wait for one tap, the notices go; live sends now
  select (ch.sending_enabled and internal.hub_setting_bool('hub_inbox_on') and g.hub_blocked_at is null and c.window_expires_at > now()) into v_ready
    from public.hub_channels ch, public.guest_profiles g where ch.id = c.channel_id and g.id = c.guest_profile_id;
  for m in select * from jsonb_array_elements(coalesce(p -> 'messages', '[]'::jsonb)) loop
    v_seq := v_seq + 1;
    v_status := case when v_test then 'test'
                     -- «بموافقة الفريق»: every reply waits for one tap; «يرد تلقائيًا»: only a licensed topic goes by itself;
                     -- the hand-off notices go out in both (approved copy, spec §2.10)
                     when t.mode in ('shadow', 'live') and not coalesce((m ->> 'notice')::boolean, false)
                          and (t.mode = 'shadow' or not coalesce((m ->> 'licensed')::boolean, false)) then 'pending_approval'
                     when not coalesce(v_ready, false) then 'failed'
                     else 'queued' end;
    insert into public.hub_messages (conversation_id, channel_id, direction, author, kind, body, payload, language, idempotency_key, status, error_code, sent_at,
                                     source_card_ids, turn_id, is_test)
    values (c.id, c.channel_id, 'out', 'assistant', case when m ->> 'kind' = 'interactive' then 'interactive' else 'text' end,
            left(m ->> 'body', 4096), coalesce(m -> 'payload', '{}'::jsonb) || jsonb_build_object('notice', coalesce((m ->> 'notice')::boolean, false), 'topics', to_jsonb(v_topics)),
            case when p ->> 'language' in ('ar', 'en') then p ->> 'language' end,
            'turn:' || t.id || ':' || coalesce(m ->> 'seq', v_seq::text), v_status,
            case when v_status = 'failed' then 'not_ready' end, now() + make_interval(secs => v_seq * 0.001),
            coalesce(array(select x::uuid from jsonb_array_elements_text(coalesce(m -> 'source_card_ids', '[]'::jsonb)) x where x ~ '^[0-9a-f-]{36}$'), '{}'),
            t.id, c.is_test)
    on conflict (idempotency_key) do nothing
    returning id into v_id;
    if v_id is not null then
      if v_status = 'queued' then
        v_send := true;
        v_out := v_out || jsonb_build_object('id', v_id, 'kind', case when m ->> 'kind' = 'interactive' then 'interactive' else 'text' end, 'body', left(m ->> 'body', 4096),
                                             'payload', coalesce(m -> 'payload', '{}'::jsonb), 'notice', coalesce((m ->> 'notice')::boolean, false));
      end if;
      if v_status = 'pending_approval' then
        update public.hub_licences set drafts = drafts + 1 where unit_id = t.unit_id and topic_key = any (v_topics);
      end if;
    end if;
  end loop;
  if v_seq > 0 and not v_test then update public.hub_conversations set last_assistant_at = now() where id = c.id; end if;
  -- «لم أعرف الإجابة» (not from a test run: nothing reaches a team)
  if not v_test and jsonb_typeof(p -> 'unanswered') = 'array' then
    perform internal.hub_unanswered_add(c, x::uuid, null, v_topics[1]) from jsonb_array_elements_text(p -> 'unanswered') x where x ~ '^[0-9a-f-]{36}$';
  end if;
  -- H10: «ما زال طلبك مع فريق الاستقبال…» went — the staff on shift alerted again (an extra alert on this conversation)
  if not v_test and coalesce((p ->> 'realert')::boolean, false) then
    perform internal.hub_extra_alert(c.id, 'still_waiting', 'ما زال الضيف ينتظر رد الفريق', null, false, null);
  end if;
  -- H11 (Ahmed, 24 Nov 2026): the guest wrote again about a booking request still with reception — the staff on shift
  -- alerted again (the request of this guest's phone, by its ref)
  if not v_test and nullif(p ->> 'realert_request', '') is not null then
    perform internal.hub_extra_alert(c.id, 'booking_request_again', 'الضيف يسأل عن طلب حجز لم يُؤكَّد', left(p ->> 'realert_request', 40), false,
      (select r.id from public.reservations r join public.guest_profiles g on g.phone = r.phone
        where g.id = c.guest_profile_id and r.ref = p ->> 'realert_request' and r.status = 'request' limit 1));
  end if;
  select unit_id into v_unit from public.hub_conversations where id = c.id;
  return jsonb_build_object('ok', true, 'cost_usd', v_cost, 'messages', v_out, 'send', v_send, 'test', v_test,
                            'alerts', exists (select 1 from public.hub_staff_sends s where s.status = 'queued' and not s.is_test),
                            'context', case when v_send then (select internal.hub_send_context(x) from public.hub_conversations x where x.id = c.id) end);
end;
$$;

create or replace function public.hub_team_cron(p_now timestamptz default now()) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  h record;
  v_esc integer := 0;
  v_rep integer;
  v_req bigint;
begin
  for h in select x.id from public.hub_handoffs x join public.hub_team_branches b on b.branch_slug = x.branch_slug
            where x.closed_at is null and x.escalated_at is null and x.opened_at is null and x.first_reply_at is null and x.alerted_at is not null and not x.extra
              and x.created_at <= p_now - make_interval(mins => b.escalate_minutes)
            order by x.created_at limit 50 for update of x skip locked loop
    v_esc := v_esc + internal.hub_handoff_queue(h.id, 'escalation', p_now);
  end loop;
  -- H10 (D1): a chat booking request still a request 15 minutes after it was made → hub_staff_alert to the branch's «مدير
  -- الاستقبال» slots and ONE alert in «التنبيهات» per request
  for h in select x.id, x.conversation_id, x.unit_id, x.ref_text, x.reservation_id from public.hub_handoffs x join public.reservations r on r.id = x.reservation_id
            where x.extra and x.reason = 'booking_request' and x.closed_at is null and x.escalated_at is null and r.status = 'request'
              and x.created_at <= p_now - interval '15 minutes'
            order by x.created_at limit 50 for update of x skip locked loop
    perform internal.hub_extra_alert(h.conversation_id, 'booking_request_late', 'طلب حجز لم يُؤكَّد بعد 15 دقيقة', h.ref_text, true, h.reservation_id);
    update public.hub_handoffs set escalated_at = p_now where id = h.id;
    insert into public.hub_alerts (kind, unit_id, payload)
    values ('booking_request', h.unit_id, jsonb_build_object('item', h.reservation_id::text, 'reservation_id', h.reservation_id, 'ref', h.ref_text))
    on conflict do nothing;
    v_esc := v_esc + 1;
  end loop;
  -- H11 (Ahmed, 24 Nov 2026): then every 60 minutes until confirmed or declined, at most 3 more — the slots on shift (the
  -- branch's managers when nobody is on shift)
  for h in select x.id, x.conversation_id, x.ref_text, x.reservation_id, x.created_at from public.hub_handoffs x join public.reservations r on r.id = x.reservation_id
            where x.extra and x.reason = 'booking_request' and x.closed_at is null and x.escalated_at is not null and r.status = 'request'
              and x.realerts < 3 and coalesce(x.realert_at, x.escalated_at) <= p_now - interval '60 minutes'
            order by x.created_at limit 50 for update of x skip locked loop
    perform internal.hub_extra_alert(h.conversation_id, 'booking_request_late',
      'طلب حجز لم يُؤكَّد منذ ' || floor(extract(epoch from (p_now - h.created_at)) / 60)::int || ' دقيقة', h.ref_text, false, h.reservation_id);
    update public.hub_handoffs set realerts = realerts + 1, realert_at = p_now where id = h.id;
    v_esc := v_esc + 1;
  end loop;
  v_rep := internal.hub_report_tick(p_now);
  update public.hub_handoffs set summary = null where summary is not null and created_at < p_now - interval '30 days';
  delete from public.hub_staff_messages where created_at < p_now - interval '30 days';
  if exists (select 1 from public.hub_staff_sends s where s.status = 'queued' and not s.is_test)
     or exists (select 1 from public.hub_daily_reports d where d.emailed_at is null and d.built_at > p_now - interval '1 day') then
    v_req := internal.hub_kick_staff_sender();
  end if;
  return jsonb_build_object('ok', true, 'escalations', v_esc, 'report', v_rep, 'request', v_req);
end;
$$;

create or replace function internal.hub_report_data(p_day date, p_to timestamptz default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_from timestamptz := (p_day::timestamp at time zone 'Asia/Riyadh');
  v_to timestamptz := coalesce(p_to, ((p_day + 1)::timestamp at time zone 'Asia/Riyadh'));
  v_branches jsonb := '{}'::jsonb;
  b text;
  v jsonb;
begin
  foreach b in array array['airport-road', 'shafa-road'] loop
    with conv as (
           select distinct c.id from public.hub_conversations c join public.hub_units u on u.id = c.unit_id join public.hub_messages m on m.conversation_id = c.id
            where u.branch_slug = b and not c.is_test and m.direction = 'in' and m.author = 'guest' and m.sent_at >= v_from and m.sent_at < v_to),
         ho as (select h.* from public.hub_handoffs h where h.branch_slug = b and not h.is_test and not h.extra and h.created_at >= v_from and h.created_at < v_to),
         sends as (select s.* from public.hub_staff_sends s join ho on ho.id = s.handoff_id)
    select jsonb_build_object(
      'conversations', (select count(*) from conv),
      'handed', (select count(distinct ho.conversation_id) from ho),
      'assistant', (select count(*) from conv where not exists (select 1 from ho where ho.conversation_id = conv.id)
                       and exists (select 1 from public.hub_messages m where m.conversation_id = conv.id and m.author = 'assistant' and m.direction = 'out'
                                     and m.status in ('accepted', 'sent', 'delivered', 'read') and m.sent_at >= v_from and m.sent_at < v_to)),
      'reply_avg_min', (select round(avg(extract(epoch from (ho.first_reply_at - ho.created_at)) / 60.0))::integer from ho where ho.first_reply_at is not null),
      'replied', (select count(*) from ho where ho.first_reply_at is not null),
      'bookings', (select count(*) from public.reservations r where r.branch = b and r.booking_source = 'assistant_whatsapp' and not r.is_test
                     and r.created_at >= v_from and r.created_at < v_to),
      -- H10 (D1): the outcome of the chat bookings of the day, as they stand («4 (3 مؤكدة، 1 ملغاة)»)
      'bookings_confirmed', (select count(*) from public.reservations r where r.branch = b and r.booking_source = 'assistant_whatsapp' and not r.is_test
                     and r.created_at >= v_from and r.created_at < v_to and r.status = 'confirmed'),
      'bookings_cancelled', (select count(*) from public.reservations r where r.branch = b and r.booking_source = 'assistant_whatsapp' and not r.is_test
                     and r.created_at >= v_from and r.created_at < v_to and r.status = 'cancelled'),
      'bookings_waiting', (select count(*) from public.reservations r where r.branch = b and r.booking_source = 'assistant_whatsapp' and not r.is_test
                     and r.created_at >= v_from and r.created_at < v_to and r.status = 'request'),
      -- H11: the chat booking requests of the day left unconfirmed more than 15 minutes (the faults line)
      'requests_late', (select count(*) from public.hub_handoffs x where x.extra and x.reason = 'booking_request' and x.branch_slug = b and not x.is_test
                     and x.escalated_at is not null and x.created_at >= v_from and x.created_at < v_to),
      'reviews', (select count(*) from public.whatsapp_messages w where w.branch = b and w.template = 'stay_review' and not w.is_test
                    and w.status in ('accepted', 'sent', 'delivered', 'read') and w.created_at >= v_from and w.created_at < v_to)
                 -- H9: and the review requests of «قائمة المغادرين»
                 + (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test
                      and d.review_state in ('accepted', 'sent', 'delivered', 'read') and d.review_at >= v_from and d.review_at < v_to),
      'unanswered', (select count(*) from public.hub_unanswered q join public.hub_units u on u.id = q.unit_id
                       where u.branch_slug = b and not q.is_test and q.created_at >= v_from and q.created_at < v_to),
      'model_failures', (select count(*) from public.hub_turns t join public.hub_units u on u.id = t.unit_id
                           where u.branch_slug = b and not t.is_test and t.status = 'failed' and t.created_at >= v_from and t.created_at < v_to),
      'send_failures', (select count(*) from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.hub_units u on u.id = c.unit_id
                          where u.branch_slug = b and not c.is_test and m.direction = 'out' and m.status = 'failed' and m.created_at >= v_from and m.created_at < v_to)
                       + (select count(*) from sends where sends.status = 'failed'),
      -- H7: the voice notes and images that failed (never a cap: it has its own email)
      'voice_failures', (select count(*) from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.hub_units u on u.id = c.unit_id
                           where u.branch_slug = b and not c.is_test and m.direction = 'in' and m.kind = 'audio'
                             and m.media_status in ('failed_download', 'failed_transcribe', 'empty', 'unknown_language') and m.created_at >= v_from and m.created_at < v_to),
      'image_failures', (select count(*) from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.hub_units u on u.id = c.unit_id
                           where u.branch_slug = b and not c.is_test and m.direction = 'in' and m.kind = 'image'
                             and m.media_status in ('failed_download', 'failed_vision') and m.created_at >= v_from and m.created_at < v_to),
      -- 15 Nov 2026: the staff alerts of the branch's hand-offs refused or failed (never silent)
      'staff_refused', (select count(*) from sends where sends.status in ('failed', 'skipped') and coalesce(sends.error_code, '') <> 'qa'),
      'alerts_sent', (select count(*) from sends where sends.status in ('accepted', 'sent', 'delivered', 'read')),
      'alerts_delivered', (select count(*) from sends where sends.status in ('delivered', 'read')),
      'alerts_read', (select count(*) from sends where sends.status = 'read'),
      'escalated', (select count(*) from ho where ho.escalated_at is not null),
      'opened', (select count(*) from ho where ho.opened_at is not null),
      'opened_link', (select count(*) from ho where ho.opened_via = 'link'),
      'email_only', (select count(*) from ho where ho.status = 'email_only'),
      'reasons', (select coalesce(jsonb_object_agg(z.reason, z.n), '{}'::jsonb) from (select coalesce(ho.reason, 'handoff') as reason, count(*) as n from ho group by 1) z),
      -- H9 «الخروج أو التمديد»: the day's departures of the list — the checks sent, «خروج», «تمديد», no answer
      'dep_on', exists (select 1 from public.hub_departure_config f where f.branch_slug = b and (f.check_on or f.review_on))
                or exists (select 1 from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day),
      'dep_rows', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day),
      'dep_sent', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day
                     and d.check_state in ('accepted', 'sent', 'delivered', 'read')),
      'dep_leave', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day and d.answer = 'leave'),
      'dep_extend', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day and d.answer = 'extend'),
      'dep_none', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day and d.answer is null
                     and d.check_state in ('accepted', 'sent', 'delivered', 'read')),
      'dep_dry', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day and d.check_state = 'dry_run'),
      'dep_late', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day
                     and d.check_state = 'skipped' and d.check_code in ('late', 'limit_late')),
      -- H9 fix 1: that day's morning list was not uploaded by 08:30 (a branch in use) — the 08:30 reminder's fault line
      'dep_missing', coalesce(p_to, now()) >= ((p_day)::timestamp + time '08:30') at time zone 'Asia/Riyadh'
                     and exists (select 1 from public.hub_departure_config f where f.branch_slug = b and f.remind_on)
                     and not exists (select 1 from public.hub_departure_uploads x where x.branch_slug = b and not x.is_test and x.departure_date = p_day
                                       and x.created_at < ((p_day)::timestamp + time '08:30') at time zone 'Asia/Riyadh')
    ) into v;
    v_branches := v_branches || jsonb_build_object(b, v);
  end loop;
  return jsonb_build_object('day', p_day, 'partial', p_to is not null, 'until', v_to, 'branches', v_branches,
    -- the daily and test reports refused or failed (they belong to no hand-off)
    'reports_refused', (select count(*) from public.hub_staff_sends s where s.kind in ('report', 'report_test') and s.status in ('failed', 'skipped')
                          and coalesce(s.error_code, '') <> 'qa' and not s.is_test and s.created_at >= v_from and s.created_at < v_to),
    -- H7b: the cards published from the dashboard (the learned ones are listed below)
    'cards', (select count(*) from public.hub_knowledge_cards k where not k.is_test and k.learn_kind is null and k.published_at >= v_from and k.published_at < v_to),
    -- H7b: the facts learned that day (teaching and staff replies), numbered for «امسح N» — still active; and what needs Ahmed's decision
    'learned', (select coalesce(jsonb_agg(jsonb_build_object('n', k.learn_no, 'short', coalesce(k.learn_short, k.title_ar), 'branch', k.learn_scope, 'kind', k.learn_kind,
                                                            'by', k.learn_by_name) order by k.learn_no), '[]'::jsonb)
                  from public.hub_knowledge_cards k where not k.is_test and k.learn_day = p_day and k.learn_no is not null and k.status <> 'archived' and k.learned_at <= v_to),
    'decisions', (select count(*) from public.hub_card_jobs j where not j.is_test and j.decision is not null and j.finished_at >= v_from and j.finished_at <= v_to),
    'budget_alerts', (select count(*) from public.hub_alerts a where a.kind in ('budget_pct', 'budget_cap', 'api_credit') and not a.is_test and a.created_at >= v_from and a.created_at < v_to),
    -- H9: the sends held back by the shared limit that day (kept and tried again — never dropped silently)
    'limit_deferred', (select count(*) from public.whatsapp_messages w where not w.is_test and w.deferred_at >= v_from and w.deferred_at < v_to)
                    + (select count(*) from public.eyab_messages e where not e.is_test and e.deferred_at >= v_from and e.deferred_at < v_to)
                    + (select count(*) from public.hub_departures d where not d.is_test and ((d.check_deferred_at >= v_from and d.check_deferred_at < v_to)
                                                                                         or (d.review_deferred_at >= v_from and d.review_deferred_at < v_to))),
    'built_at', now());
end;
$$;

create or replace function public.hub_departure_answer(p_phone text, p_channel text, p_choice text, p_via text, p_id uuid, p_conversation uuid,
                                            p_body text default null, p_test boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  d public.hub_departures;
  c public.hub_conversations;
  v_branch text;
  v_today date := internal.riyadh_today();
  v_msg uuid;
  v_ctx jsonb;
begin
  if p_choice not in ('leave', 'extend') or p_via not in ('button', 'typed') then raise exception 'hub_departure_answer' using errcode = '22023'; end if;
  -- hub-agent (a typed answer) names the conversation only: its guest's phone and number are read here (never handed out)
  if p_phone is null and p_conversation is not null then
    select g.phone, ch.address into p_phone, p_channel from public.hub_conversations x join public.guest_profiles g on g.id = x.guest_profile_id
      join public.hub_channels ch on ch.id = x.channel_id where x.id = p_conversation;
  end if;
  if p_phone is null then return jsonb_build_object('matched', false); end if;
  select u.branch_slug into v_branch from public.hub_channels ch join public.hub_units u on u.id = ch.unit_id where ch.address = p_channel and u.kind = 'branch' limit 1;
  select * into d from public.hub_departures x
   where (p_id is null or x.id = p_id) and x.phone = p_phone and x.is_test = coalesce(p_test, false) and (v_branch is null or x.branch_slug = v_branch)
     and x.check_state in ('accepted', 'sent', 'delivered', 'read', 'test') and x.departure_date between v_today - 1 and v_today
   order by x.departure_date desc, x.check_at desc limit 1 for update;
  if d.id is null then return jsonb_build_object('matched', false); end if;
  if d.answer is not null then return jsonb_build_object('matched', true, 'already', true, 'answer', d.answer, 'language', d.language); end if;
  perform set_config('app.actor', 'guest', true);
  if p_choice = 'leave' then
    update public.hub_departures
       set answer = 'leave', answer_via = p_via, answer_at = now(),
           review_due_at = case when review_state = 'scheduled'
                                then greatest(((departure_date)::timestamp + time '19:00') at time zone 'Asia/Riyadh', now() + interval '30 minutes') else review_due_at end
     where id = d.id returning * into d;
  else
    update public.hub_departures
       set answer = 'extend', answer_via = p_via, answer_at = now(),
           review_state = case when review_state in ('scheduled', 'queued') then 'cancelled' else review_state end,
           review_code = case when review_state in ('scheduled', 'queued') then 'extended' else review_code end
     where id = d.id returning * into d;
  end if;
  -- a button: the hand-off and the reply are made here; a typed answer: the engine has made both already
  if p_conversation is not null and p_via = 'button' then
    select * into c from public.hub_conversations where id = p_conversation for update;
  end if;
  if c.id is not null then
    -- H11 (Ahmed, 24 Nov 2026): «أرغب في التمديد» asks the date first («حتى أي تاريخ ترغب في التمديد؟») — an open «extend»
    -- draft waits for it and the engine hands off with the date; a conversation already with staff keeps the hand-off
    if p_choice = 'extend' and c.state <> 'human' then
      update public.hub_drafts set status = 'superseded', updated_at = now() where conversation_id = c.id and status = 'open';
      insert into public.hub_drafts (conversation_id, kind, sim, fields, is_test)
      values (c.id, 'extend', false, jsonb_build_object('nazeel_ref', d.nazeel_ref, 'check_in', d.departure_date, '_asked', 1), c.is_test);
      update public.hub_conversations set state = 'collecting', tags = array(select distinct x from unnest(tags || array['تمديد']) x)
       where id = c.id returning * into c;
    elsif p_choice = 'extend' then
      perform internal.hub_to_team(c, 'extension');
      update public.hub_conversations set tags = array(select distinct x from unnest(tags || array['تمديد']) x), waiting_since = coalesce(waiting_since, now())
       where id = c.id returning * into c;
      update public.hub_handoffs set summary = 'يطلب تمديد الإقامة', ref_text = left('نزيل ' || d.nazeel_ref, 40) where id = c.handoff_id;
      insert into public.hub_messages (conversation_id, channel_id, direction, author, kind, body, payload, idempotency_key, status, sent_at, is_test)
      values (c.id, c.channel_id, 'out', 'system', 'note', left('يريد: تمديد الإقامة — رقم الحجز في نزيل ' || d.nazeel_ref, 2000), jsonb_build_object('handoff_note', true),
              'departure:' || d.id || ':' || d.cycle || ':note', 'internal', now(), c.is_test)
      on conflict (idempotency_key) do nothing;
    end if;
    if nullif(btrim(coalesce(p_body, '')), '') is not null then
      insert into public.hub_messages (conversation_id, channel_id, direction, author, kind, body, payload, language, idempotency_key, status, sent_at, is_test)
      values (c.id, c.channel_id, 'out', 'assistant', 'text', left(btrim(p_body), 4096),
              jsonb_build_object('notice', p_choice = 'extend' and c.state = 'human', 'handoff', p_choice = 'extend' and c.state = 'human', 'departure', p_choice),
              d.language, 'departure:' || d.id || ':' || d.cycle || ':reply', case when coalesce(p_test, false) then 'test' else 'queued' end, now(), c.is_test)
      on conflict (idempotency_key) do nothing
      returning id into v_msg;
      if v_msg is not null and not coalesce(p_test, false) then
        begin
          v_ctx := internal.hub_send_context(c);
        exception when others then
          update public.hub_messages set status = 'failed', error_code = 'not_ready' where id = v_msg;
          v_ctx := null;
        end;
      end if;
    end if;
  end if;
  return jsonb_build_object('matched', true, 'already', false, 'answer', d.answer, 'language', d.language, 'branch', d.branch_slug, 'ref', d.nazeel_ref,
                            'conversation_id', c.id, 'message_id', v_msg, 'context', v_ctx, 'handoff_id', c.handoff_id);
end;
$$;

-- ───────────────────────────────────────────── 4. the bank ─────────────────────────────────────────────

update public.hub_test_items
   set expect = '{"action": "conversation", "steps": [{"outcome": "ask"},{"outcome": "ask"},{"outcome": "quote", "cards": [1,3], "must_not_include": ["تأكيد فوري"]},{"outcome": "ask"},{"outcome": "summary", "must_include": ["محمد أحمد", "سيصل طلبك إلى فريق الاستقبال ليؤكده لك هنا في أقرب وقت"], "must_not_include": ["يتأكد حجزك فورًا"]},{"outcome": "booked", "must_include": ["AR-", "وسيؤكده لك فريق الاستقبال هنا في أقرب وقت"]}]}'::jsonb
 where key = 'h10-01' and expect = '{"action": "conversation", "steps": [{"outcome": "ask"},{"outcome": "ask"},{"outcome": "quote", "cards": [1,3], "must_not_include": ["تأكيد فوري"]},{"outcome": "ask"},{"outcome": "summary", "must_include": ["محمد أحمد", "سيصل طلبك إلى فريق الاستقبال ليؤكده لك هنا خلال دقائق"], "must_not_include": ["يتأكد حجزك فورًا"]},{"outcome": "booked", "must_include": ["AR-", "وسيؤكده لك فريق الاستقبال هنا خلال دقائق"]}]}'::jsonb;
update public.hub_test_items
   set expect = '{"action": "conversation", "steps": [{"outcome": "ask"},{"outcome": "quote", "cards": [1,3], "must_not_include": ["Instant confirmation"]},{"outcome": "ask"},{"outcome": "summary", "must_include": ["Sara Ali", "reception team", "as soon as possible"]},{"outcome": "booked", "must_include": ["AR-", "booking request"]}]}'::jsonb
 where key = 'h10-02' and expect = '{"action": "conversation", "steps": [{"outcome": "ask"},{"outcome": "quote", "cards": [1,3], "must_not_include": ["Instant confirmation"]},{"outcome": "ask"},{"outcome": "summary", "must_include": ["Sara Ali", "reception team", "within minutes"]},{"outcome": "booked", "must_include": ["AR-", "booking request"]}]}'::jsonb;
do $$
declare v_sort integer := coalesce((select max(sort) + 1 from public.hub_test_items), 0);
begin
  insert into public.hub_test_items (key, unit_key, language, messages, context, expect, note, tags, added_from, sort)
  select e ->> 'key', e ->> 'unit', e ->> 'language', e -> 'messages', coalesce(e -> 'context', '{}'::jsonb), e -> 'expect', e ->> 'note',
         array(select jsonb_array_elements_text(e -> 'tags')), 'seed', v_sort + (o - 1)::integer
    from jsonb_array_elements($h11_bank$[{"key":"h11-01","unit":"airport-road","language":"ar","messages":["[unsupported]","[unsupported]"],"expect":{"action":"conversation","steps":[{"outcome":"reply","must_include":["لم نتمكن من فتحها"]},{"outcome":"handoff"}]},"note":"7eb95d07 paraphrased: a message type the router cannot open — one question to type it as text; a second one in a row → the team","tags":["conversation","h11","unsupported"],"context":{}},{"key":"h11-02","unit":"airport-road","language":"ar","messages":["أبغى أحجز غرفة لشخصين، الوصول اليوم ظهرًا والمغادرة بكرة"],"expect":{"action":"conversation","steps":[{"outcome":"ask","must_include":["الإفطار"],"must_not_include":["ما تاريخ وصولك","متى موعد وصولك"]}]},"note":"4d9cf8aa paraphrased: «الوصول اليوم ظهرًا والمغادرة بكرة» — today → tomorrow, read by code; the next question is breakfast, never the dates again","tags":["conversation","h11","dates"],"context":{}},{"key":"h11-03","unit":"airport-road","language":"ar","messages":["أبغى أحجز غرفة لشخصين","٢٦ لين ٣٠"],"expect":{"action":"conversation","steps":[{"outcome":"ask"},{"outcome":"ask","must_not_include":["ما تاريخ وصولك","متى موعد وصولك","سيكمل معك"]}]},"note":"b69f08cc paraphrased: two bare days «٢٦ لين ٣٠» answer the date question — never asked again","tags":["conversation","h11","dates"],"context":{}},{"key":"h11-04","unit":"shafa-road","language":"ar","messages":["هل عندكم مواقف للسيارات؟"],"expect":{"action":"conversation","steps":[{"outcome":["answer","reply"],"must_include":["لا يزال لدى فريق الاستقبال","مواقف"]}]},"note":"8fc92754 paraphrased: a guest with a booking request still with reception writes again — the request first, then the answer","tags":["conversation","h11","pending_request"],"context":{"bookings":[{"status":"request","in_days":5,"nights":2,"room":"king-room","adults":2,"branch":"shafa-road"}]}},{"key":"h11-05","unit":"airport-road","language":"ar","messages":["تمديد","إلى بعد بكرة"],"expect":{"action":"conversation","steps":[{"outcome":"departure_extend","must_include":["حتى أي تاريخ"]},{"outcome":"departure_extend","must_include":["سجّلنا طلب التمديد حتى"]}]},"note":"8da7c373 paraphrased: «تمديد» to the departure check — the date first, then «سجّلنا طلب التمديد حتى …» and the team","tags":["conversation","h11","extension"],"context":{"departure_check":true}},{"key":"h11-06","unit":"airport-road","language":"ar","messages":["عندي حجز مؤكد من 3 ديسمبر لمدة 4 ليالي وأبي أقدّمه إلى 2 ديسمبر، هل يصح؟"],"expect":{"action":"conversation","steps":[{"outcome":"handoff","must_not_include":["الإجمالي"]}]},"note":"bd27baf4 (19 Nov 10:50) paraphrased: a change to a booking the guest already has → the change notice and the team, never room cards","tags":["conversation","h11","booking_change"],"context":{}},{"key":"h11-07","unit":"shafa-road","language":"ar","messages":["أبغى غرفتين وصالة من 10 ديسمبر إلى 12 ديسمبر لأربعة أشخاص","بدون إفطار"],"expect":{"action":"conversation","steps":[{"outcome":"ask"},{"outcome":"quote","must_include":["جناح بغرفتي نوم وصالة"],"must_not_include":["أكثر من غرفة"]}]},"note":"0fb68f52 paraphrased: «غرفتين وصالة» is ONE two-bedroom suite, never two one-bedroom suites","tags":["conversation","h11","room_words"],"context":{}},{"key":"h11-08","unit":"airport-road","language":"ar","messages":["أبغى غرفة مهيأة لذوي الاحتياجات الخاصة من 10 ديسمبر إلى 12 ديسمبر لشخصين","بدون إفطار"],"expect":{"action":"conversation","steps":[{"outcome":["ask","answer"]},{"outcome":["quote","ask"],"must_include":["غير متاح للحجز","طريق الشفا"]}]},"note":"a type switched off in «الغرف» at this branch (the accessible room at Airport Road on 24 Nov 2026) and on at the other: never offered here; the other branch offered (depends on «الغرف» — re-check when Ahmed switches it on)","tags":["conversation","h11","room_off"],"context":{}},{"key":"h11-09","unit":"airport-road","language":"ar","messages":["[burst] أبغى أحجز من 10 ديسمبر إلى 12 ديسمبر ‖ لشخصين"],"expect":{"action":"conversation","steps":[{"o